// Generated by the documents input projection. Values remain in their committed carriers.

/// A declared numeric pin; removing an id removes its variant.
#[derive(Clone, Copy, Debug)]
pub enum NumberId {
    /// Registry id: num:numbers:records-burn-corruption-count.
    NumbersRecordsBurnCorruptionCount,
    /// Registry id: num:numbers:records-burn-marker-count.
    NumbersRecordsBurnMarkerCount,
    /// Registry id: num:numbers:records-dag-corruption-count.
    NumbersRecordsDagCorruptionCount,
    /// Registry id: num:numbers:records-dag-history-count.
    NumbersRecordsDagHistoryCount,
    /// Registry id: num:numbers:records-dag-history-epoch.
    NumbersRecordsDagHistoryEpoch,
    /// Registry id: num:numbers:records-dag-over-bound-count.
    NumbersRecordsDagOverBoundCount,
    /// Registry id: num:numbers:records-dag-proposal-epoch.
    NumbersRecordsDagProposalEpoch,
    /// Registry id: num:numbers:records-dag-proposal-maximum.
    NumbersRecordsDagProposalMaximum,
    /// Registry id: num:numbers:records-dag-proposal-minimum.
    NumbersRecordsDagProposalMinimum,
    /// Registry id: num:numbers:records-dag-word-capacity.
    NumbersRecordsDagWordCapacity,
    /// Registry id: num:numbers:records-numeric-case-count.
    NumbersRecordsNumericCaseCount,
    /// Registry id: num:numbers:reference-rational-floor.
    NumbersReferenceRationalFloor,
}

const OFFSETS: [(usize, usize); 12] = [
    (136, 138),
    (204, 205),
    (274, 276),
    (342, 343),
    (409, 410),
    (479, 480),
    (547, 548),
    (617, 619),
    (688, 689),
    (755, 756),
    (823, 824),
    (889, 893),
];

impl NumberId {
    /// Read the full-precision value from the committed registry.
    ///
    /// # Panics
    /// Panics only if generated offsets differ from the registry, which the fixed-point gate refuses.
    #[must_use]
    pub fn value(self) -> &'static str {
        let (start, end) = OFFSETS[self as usize];
        include_str!("pins_records.toml")
            .get(start..end)
            .expect("registry offsets must be regenerated")
    }

    /// Read an unsigned integer pin without a second literal.
    ///
    /// # Panics
    /// Panics only if the selected pin is not an unsigned machine integer, which a correctly typed consumer selection cannot arrange.
    #[must_use]
    pub fn integer(self) -> u64 {
        self.value().parse().expect("registry pin must be an unsigned integer")
    }
}
